import csv
import json
import statistics
from pathlib import Path

ROOT=Path(__file__).resolve().parent
J=lambda n: json.loads((ROOT/n).read_text(encoding='utf8'))
ARM={'lex_absent':'Лексический, без правок','lex_shuffle':'Лексический, перемещённые правки','lex_real':'Лексический, свои правки','hyb_absent':'Гибридный, без правок','hyb_shuffle':'Гибридный, перемещённые правки','hyb_real':'Гибридный, свои правки'}
fmt=lambda x,n=1:f'{x:.{n}f}'.replace('.',',').replace('-','−')
def line(d):
    return f"Δ {fmt(100*d['delta'],2)} п. п., 95% ДИ [{fmt(100*d['repo_ci95'][0],2)}; {fmt(100*d['repo_ci95'][1],2)}]"
def main():
    res=J('results.json')['cohorts']; c=J('costs.json')
    text=['# Что добавляют наблюдавшиеся правки при индексировании опыта','',
          'На этапе завершения прежней задачи память сохраняет симптом со слов пользователя, последнюю открытую заметку агента и отдельный ключ из путей и идентификаторов, встретившихся в попытках редактирования. Здесь измерен вклад **этого третьего ключа в ранжирование до подачи контекста решателю**. Выдача ограничена пятью историями. Решатель не вызывался.','',
          'Один фактор меняет поисковый механизм — лексический или гибридный с двумя фиксированными векторными представлениями. Второй меняет только поле правок. Контроль с перестановкой сохраняет число полей, совокупность слов и байтов, число ненулевых лексических признаков и веса. Пропуск поля экономит индексирование.','',
          '## Все 99 задач SWE-ContextBench Lite','',
          '| Метод | Match@1 | Hit@5 | MRR по 300 | Macro Recall@5 |','|---|---:|---:|---:|---:|']
    for arm,label in ARM.items():
        s=res['lite']['methods'][arm]
        text.append(f"| {label} | {s['match1']}/99 | {s['hit5']}/99 | {fmt(s['mrr'],4)} | {fmt(s['macro_recall5'],4)} |")
    text+=['','Hit@5 означает наличие хотя бы одной официальной связи. Macro Recall@5 усредняет долю всех известных связей каждого вопроса; эти числа могут различаться при нескольких правомерных прошлых историях. В MRR для каждого вопроса берётся первая допустимая история.','',
           '## Заранее назначенные пары','']
    g=res['lite']
    for k,lab in [('hyb_real-hyb_absent','Правильная привязка минус пропуск поля'),('hyb_real-hyb_shuffle','Правильная привязка минус перестановка')]:
        v=g['paired'][k]['hit5'];t=g['paired'][k]['match1']
        text.append(f"- **{lab}.** Для Hit@5 выиграно {v['wins']}, проиграно {v['losses']}; {line(v)}, точный двусторонний p = {fmt(v['mcnemar_exact_p'],4)}, p Холма = {fmt(v['holm_pair_p'],4)}. Для первой позиции {t['wins']} выигрышей и {t['losses']} потерь; {line(t)}.")
    text.extend(['',f"Взаимодействие двух факторов по Hit@5 (эффект добавления правок в гибридном поиске минус эффект в лексическом) — {line(g['hit5_interaction'])}. Парный bootstrap выбирает целые репозитории с повторениями. В Lite их {g['repos']}. Точный тест Мак-Немара трактует задачи как независимые единицы, поэтому межзадачная зависимость в пределах репозитория ограничивает вывод. Две основные проверки по Hit@5 скорректированы совместно. Остальные сравнения описательны.",'',
                 '## Дополнительные 258 задач','',
                 'Это disjoint-по-запросам диагностическая часть официальной базы. Библиотека осталась прежней. Поэтому лишь часть вопросов может получить правильный результат даже при идеальном ранжировании.','',
                 '| Метод | Match@1, все 258 | Hit@5, все 258 | MRR, все 258 | Hit@5, эталон доступен |','|---|---:|---:|---:|---:|'])
    ext=res['extension'];avail=res['extension_available']
    for arm,label in ARM.items():
        b=ext['methods'][arm];a=avail['methods'][arm]
        text.append(f"| {label} | {b['match1']} | {b['hit5']} | {fmt(b['mrr'],4)} | {a['hit5']}/{avail['n']} |")
    text.extend(['',f"Допустимый предыдущий опыт доступен у {ext['available']} из {ext['n']} дополнительных вопросов. В соответствующем условном подмножестве всего {avail['repos']} репозитория. Перенос эффекта на независимый новый корпус этим срезом убедительно проверить нельзя.",'',
                 '## Затраты и происхождение данных',''])
    fields=c['corpus'];tbytes=sum(z['bytes_utf8'] for z in fields.values());bbytes=fields['edits']['bytes_utf8']
    text.append(f"Поле правок заняло {bbytes:,} байт UTF-8 из {tbytes:,} байт трёх текстовых полей ({fmt(100*bbytes/tbytes)}%). Его отдельный индекс BM25 содержит {fields['edits']['bm25_postings']:,} пар документ–термин. Число пар описывает размер логического индекса; байтовый размер структур Python и сериализованного поискового сервиса другой. Общие неизменные векторы двух полей документов составляют {c['two_doc_vector_arrays_bytes']:,} байт в FP32. Число GPU-вызовов и LLM-вызовов равно нулю.")
    donor=list(csv.DictReader((ROOT/'donors.csv').open(encoding='utf8')))
    dlen=[abs(int(v['source_nwords'])-int(v['donor_nwords'])) for v in donor]
    text.extend(['',f"Контроль переставил все {len(donor)} привязок, полный текст совпал у {sum(int(v['same_text']) for v in donor)} пар источник–донор. Абсолютная разница длин внутри назначений составила в среднем {fmt(statistics.mean(dlen),2)} слова, максимум {max(dlen)}. Переставленная выдача вычисляется перестановкой исходных BM25-оценок с той же устойчивой сортировкой. Независимое повторное индексирование переставленных документов дало ту же матрицу до сортировки.",
                 '',f"Исходные top-10 воспроизведены для всех {c['reference_top10_parity']['hyb_real']} гибридных и {c['reference_top10_parity']['lex_real']} лексических запросов. Три CPU-потока, PyTorch {c['torch']}, Transformers {c['transformers']}. Времена по каждому этапу и пиковая рабочая память в costs.json. Время CPU не оценивает задержку или стоимость последующего агента.",'',
                 '## Воспроизведение','',
                 'Для повторной проверки сохранённых чисел выполните python verify.py в этом каталоге с NumPy. Для полного пересчёта нужен предыдущий набор артефактов SWE-ContextBench (SWE_CONTEXT_BASE), локальный facebook/contriever (CONTRIEVER_PATH), PyTorch, Transformers, NumPy и psutil. Задайте CUDA_VISIBLE_DEVICES=-1, OPENBLAS_NUM_THREADS=1, OMP_NUM_THREADS=3, MKL_NUM_THREADS=3, HF_HUB_OFFLINE=1 и PYTHONDONTWRITEBYTECODE=1. Запустите generate.py freeze, generate.py predict, score.py, verify.py, summarize.py. Изначальная заморозка и её время сохраняются в design-lock.json. Слепой полный список в rankings.npz зафиксирован в predictions-lock.json до открытия таблицы связей. Метка source key извлекается из keys.json по смещению. Таблица per_query.csv содержит все позиции и исходы, scoring-inputs.json — минимальную проекцию для независимой проверки.', '',
                 'Ранее агрегаты того же теста уже были известны. Новые условия были записаны до вычисления прогнозов. Строгая причинная интерпретация относится к перестановке или удалению поля в заданном алгоритме для этого корпуса. Пары документов ограничены по длине; одна фиксированная перестановка не даёт интервала по возможным назначениям. Слова, связанные с правкой, могут сохраняться в симптоме и итоговой заметке. Исследование не устанавливает успех исправления кода или удобство той же записи для другой модели.', '',
                 'Публичные первоисточники: [код SWE-ContextBench](https://github.com/jiayuanz3/SWEContextBench/tree/12ad6ab14e18e9378e1e293c9edbc3f7ce43d27b), [версия базы связей](https://huggingface.co/datasets/jiayuanz3/SWEContextBench/tree/12c65bd15e2559bc808065565e941ee7bbbd008f).'])
    (ROOT/'README_RU.md').write_text('\n'.join(text)+'\n',encoding='utf8')

if __name__=='__main__': main()

